<?php
/**
 * tz_reference.class.php
 * @author Patrick Emond <emond@mcmaster.ca>
 */

namespace alder\business;
use cenozo\lib, cenozo\log, alder\util;

/**
 * Computes T and Z scores
 *
 * The REFERENCE_LIST const array is generated by first loading the Apex reference database into a temporary table:
 * 
 * apt-get install mdbtools
 * mdb-schema reference.mdb mysql' => [mysql temporary_db
 * mdb-export -D '%Y-%m-%d %H:%M:%S' -I mysql reference.mdb ReferenceCurve' => [mysql temporary_db
 * mdb-export -D '%Y-%m-%d %H:%M:%S' -I mysql reference.mdb Points' => [mysql temporary_db
 * 
 * Then, the static data in the Referencurve and Points tables are compiled into an associative array to be used
 * by this utility.  The data was collected using the following query:
 * 
 * SELECT
 *   CONCAT_WS(
 *     ";",
 *     reftype,
 *     sex,
 *     IFNULL( ethnic, "_" ),
 *     IF( method = "Apex", "A", "_" ),
 *     IF( source LIKE "%Hologic%", "H", "N" ),
 *     IFNULL( bonerange, "_" )
 *   ) as lookup,
 *   age_young,
 *   GROUP_CONCAT( CONCAT( X_VALUE, ":", Y_VALUE, ",", L_VALUE, ",", STD ) ) points
 * FROM ReferenceCurve
 * JOIN Points USING (UNIQUE_ID)
 * WHERE reftype IN ("R", "H", "L", "S", "W")
 * AND if_current = 1
 * AND (source LIKE "%NHANES%" OR source LIKE "%Hologic%")
 * AND y_label = "IDS_REF_LBL_BMD"
 * AND ( method IS NULL OR method = "Apex" )
 * GROUP BY UNIQUE_ID
 * ORDER BY reftype, sex, ethnic, method, source, bonerange, unique_id;
 * 
 * The data is grouped into an associative array where the keys are the unique reftype, sex, ethnic, method, source
 * and bonerange, concatenated together and and separated by a semicolon.
 * The values are all an array with two elements:
 *   1) the x-value that defines the "age young" key in the points array
 *   2) an associative points array that has the x-value as the key and an arry with three elements as the value:
 *      y_value, l_value and std (always in that order)
 * 
 * So for example:
 * 
 * [
 *   'reftype;sex;ethnic;method;source;bonerange' => [
 *     age_young,
 *     [
 *       x_value_1 => [y_value, l_value, std],
 *       x_value_2 => [y_value, l_value, std],
 *       x_value_3 => [y_value, l_value, std],
 *       etc...
 *     ]
 *   ]
 * ]
 * 
 * Where:
 *   reftype is one of: D, H, L, R, S, V, or W
 *   sex is one of: F or M
 *   ethnic is one of: _, B, H, or P
 *   method is one of: _ or A (NULL or Apex, respectively)
 *   source is one of: H or N (Hologic or NHANES, respectively)
 *   bonerange is the bonerange value (or '_' if it is null)
 */
class tz_reference extends \cenozo\base_object
{
  /**
   * Computes all T and Z scores for any DXA scan as an associative array
   * 
   * @param string $type One of hip, spine, forearm, lateral or wbody
   * @param string $side One of right or left (used for forearm and hip only, otherwise ignored)
   * @param associative array $apex_data
   *   Note that the following variables are expected in the $apex_data parameter:
   *     "scan_date" The date the scan was taken in YYYY-MM-DD format
   *     "birthdate" The participant's date of birth in YYYY-MM-DD format
   *     "sex" (M or F)
   *     "ethnicity" (W, O, P, I, H, or B)
   * @return associative array
   */
  function compute_tz_scores( $type, $side, $apex_data )
  {
    $score_data = [];

    $bonerange_list = [
      // forearm
      'ru13tot_bmd' => '1..',
      'rumidtot_bmd' => '.2.',
      'ruudtot_bmd' => '..3',
      'rutot_bmd' => '123',
      'r_13_bmd' => 'R..',
      'r_mid_bmd' => '.R.',
      'r_ud_bmd' => '..R',
      'rtot_bmd' => 'RRR',
      'u_13_bmd' => 'U..',
      'u_mid_bmd' => '.U.',
      'u_ud_bmd' => '..U',
      'utot_bmd' => 'UUU',

      // whole body
      'wbtot_bmd' => '_',

      // hip
      'neck_bmd' => '1...',
      'troch_bmd' => '.2..',
      'inter_bmd' => '..3.',
      'wards_bmd' => '...4',
      'htot_bmd' => '123.',

      // ap lumbar spine
      'l1_bmd' => '1...',
      'l2_bmd' => '.2..',
      'l3_bmd' => '..3.',
      'l4_bmd' => '...4',
      'tot_bmd' => '1234',
      'tot_l1_bmd' => '1...',
      'tot_l2_bmd' => '.2..',
      'tot_l3_bmd' => '..3.',
      'tot_l4_bmd' => '...4',
      'tot_l1l2_bmd' => '12..',
      'tot_l1l3_bmd' => '1.3.',
      'tot_l1l4_bmd' => '1..4',
      'tot_l2l3_bmd' => '.23.',
      'tot_l2l4_bmd' => '.2.4',
      'tot_l3l4_bmd' => '..34',
      'tot_l1l2l3_bmd' => '123.',
      'tot_l1l2l4_bmd' => '12.4',
      'tot_l1l3l4_bmd' => '1.34',
      'tot_l2l3l4_bmd' => '.234',
    ];

    $source = 'N'; // NHANES
    $prefix = NULL;
    $reftype = NULL;
    if( 'forearm' == $type )
    {
      $source = 'H'; // Hologic
      $prefix = sprintf( '%s_fa_', $side );
      $reftype = 'R';
    }
    else if( 'hip' == $type )
    {
      $prefix = sprintf( '%s_hip_', $side );
      $reftype = 'H';
    }
    else if( 'lateral' == $type )
    {
      $prefix = 'del_';
      $reftype = 'L';
    }
    else if( 'spine' == $type )
    {
      $source = 'H'; // Hologic
      $prefix = 'sp_';
      $reftype = 'S';
    }
    else if( 'wbody' == $type )
    {
      $prefix = 'wb_';
      $reftype = 'W';
    }

    $bmd_data = [];

    if( 'spine' == $type )
    {
      // AP lumbar spine:
      // - identify the included vertebral levels
      // - sum the area and sum the bmc of the included vertebral levels
      // - compute the revised total bmd from summed bmc / summed area
      // - provide the proper bone range code for total bmd

      $inc_list = [false, false, false, false];

      $area_list = [0.0, 0.0, 0.0, 0.0];
      $bmc_list = [0.0, 0.0, 0.0, 0.0];
      $tot_bmd = 0.0;

      foreach( $apex_data as $key => $value )
      {
        $index = -1;
        if( preg_match( '/^l1/', $key ) ) $index = 0;
        else if( preg_match( '/^l2/', $key ) ) $index = 1;
        else if( preg_match( '/^l3/', $key ) ) $index = 2;
        else if( preg_match( '/^l4/', $key ) ) $index = 3;

        if( -1 != $index )
        {
          if( preg_match( '/_included$/', $key ) ) $inc_list[$index] = $value;
          else if( preg_match( '/_area$/', $key ) ) $area_list[$index] = $value;
          else if( preg_match( '/_bmc$/', $key ) ) $bmc_list[$index] = $value;
        }

        if( preg_match( '/_bmd$/', $key ) )
        {
          $key = preg_replace( sprintf( '/%s/', $prefix ), '', $key );
          if( 'tot_bmd' == $key ) $tot_bmd = $value;
          else if( array_key_exists( $key, $bonerange_list ) ) $bmd_data[$key] = $value;
        }
      }

      $tot_area = 0.0;
      $tot_bmc = 0.0;

      for( $i = 0; $i < 4; $i++ )
      {
        if( $inc_list[$i] )
        {
          $tot_area += $area_list[$i];
          $tot_bmc += $bmc_list[$i];
        }
      }

      if( 0.0 != $tot_area ) $tot_bmd = $tot_bmc / $tot_area;

      // the tot_key depends on which lumbar was included (l1, l2, l3, l4)
      $k = '';
      if( $inc_list[0] ) $k .= 'l1';
      if( $inc_list[1] ) $k .= 'l2';
      if( $inc_list[2] ) $k .= 'l3';
      if( $inc_list[3] ) $k .= 'l4';
      $tot_key = '' == $k ? 'tot_bmd' : sprintf( 'tot_%s_bmd', $k );

      if( array_key_exists( $tot_key, $bonerange_list ) ) $bmd_data[$tot_key] = $tot_bmd;
    }
    else
    {
      foreach( $apex_data as $key => $value )
      {
        if( preg_match( '/_bmd$/', $key ) )
        {
          $new_key = str_replace( $prefix, '', $key );
          if( array_key_exists( $new_key, $bonerange_list ) ) $bmd_data[$new_key] = $value;
        }
      }
    }

    $scan_date_obj = util::get_datetime_object( $apex_data['scan_date'] );
    $date_of_birth_obj = util::get_datetime_object( $apex_data['birthdate'] );
    // calculate age (to the second because that's how the original algorithm did it)

    $age = ($scan_date_obj->getTimestamp() - $date_of_birth_obj->getTimestamp()) / (60 * 60 * 24 * 365.25);

    $age_min = NULL;
    $age_max = NULL;

    foreach( $bmd_data as $bmd_key => $bmd_value )
    {
      // DETERMINE THE T SCORE AND PR VALUE ////////////////////////////////////////////////////////
      $t_score_name = (
        'spine' == $type && preg_match( '/^tot_/', $bmd_key ) ?
        'tot_t' :
        str_replace( '_bmd', '_t', $bmd_key )
      );

      $pr_value_name = (
        'spine' == $type && preg_match( '/^tot_/', $bmd_key ) ?
        'tot_pr' :
        str_replace( '_bmd', '_pr', $bmd_key )
      );

      // build the reference key by concatenating the key values with a semicolon (;)
      $reference_key = implode(
        ';',
        [
          $reftype,
          'F', // sex
          '_', // ethnic
          'spine' == $type && preg_match( '/L[14]_/', $bmd_key ) ? 'A' : '_', // method
          $source,
          array_key_exists( $bmd_key, $bonerange_list ) ? $bonerange_list[$bmd_key] : '_'
        ]
      );

      if( array_key_exists( $reference_key, self::REFERENCE_LIST ) )
      {
        $reference = self::REFERENCE_LIST[$reference_key];
        $age_young = $reference[0];
        $points = $reference[1];
        $x_value = $bmd_value;
        $y_value = $points[$age_young][0];
        $l_value = $points[$age_young][1];
        $std = $points[$age_young][2];

        $t_score = $y_value * ( pow( $x_value / $y_value, $l_value ) - 1.0 ) / ( $l_value * $std );
        if( self::$debug ) log::debug( sprintf( 'Setting: %s => %s', $t_score_name, $t_score ) );
        $score_data[$t_score_name] = $t_score;

        $pr_value = 100 * $x_value / $y_value;
        if( self::$debug ) log::debug( sprintf( 'Setting: %s => %s', $pr_value_name, $pr_value ) );
        $score_data[$pr_value_name] = $pr_value;
      }
      else
      {
        log::warning( sprintf( 'Invalid reference key "%s" found while computing T score', $reference_key ) );
        continue;
      }

      // DETERMINE THE Z SCORE AND AM VALUE ////////////////////////////////////////////////////////
      $z_score = 0;
      $z_score_name = (
        'spine' == $type && preg_match( '/^tot_/', $bmd_key ) ?
        'tot_z' :
        str_replace( '_bmd', '_z', $bmd_key )
      );

      $am_value = 0;
      $am_value_name = (
        'spine' == $type && preg_match( '/^tot_/', $bmd_key ) ?
        'tot_am' :
        str_replace( '_bmd', '_am', $bmd_key )
      );

      // U_UD_BMD for males is always 0
      if( 'M' != $apex_data['sex'] || 'u_ud_bmd' != $bmd_key )
      {
        // build the reference key by concatenating the key values with a semicolon (;)
        $reference_key = implode(
          ';',
          [
            $reftype,
            $apex_data['sex'],
            is_null( $apex_data['ethnicity'] ) ||
              in_array( $apex_data['ethnicity'], ['', 'W', 'O', 'P', 'I'] ) ||
              (
                'forearm' == $type &&
                in_array( $apex_data['ethnicity'], ['H', 'B'] )
              ) ? '_' : $apex_data['ethnicity'],
            'spine' == $type && preg_match( '/l[14]_/', $bmd_key ) ? 'A' : '_', // method
            $source,
            is_null( $bonerange_list[$bmd_key] ) ? '_' : $bonerange_list[$bmd_key]
          ]
        );

        if( !array_key_exists( $reference_key, self::REFERENCE_LIST ) )
        {
          log::warning( sprintf( 'Invalid reference key "%s" found while computing Z score', $reference_key ) );
        }

        $reference = self::REFERENCE_LIST[$reference_key];
        $points = $reference[1];
        $age_list = array_keys( $points );

        // determine the age bracket
        for( $i = 0; $i < count( $age_list )-1; $i++ )
        {
          $min = $age_list[$i];
          $max = $age_list[$i+1];

          if( $min <= $age && $age <= $max )
          {
            $age_min = $min;
            $age_max = $age == $min ? $min : $max;
          }
          else if( $age > $max )
          {
            $age_min = $max;
            $age_max = $max;
          }
        }

        if( is_null( $age_min ) ) $age_min = $age;
        if( is_null( $age_max ) ) $age_max = $age;

        $age_bracket = [
          'min' => $age_min,
          'max' => $age_max,
          'span' => $age_max - $age_min
        ];

        if( 0 != $age_bracket['span'] )
        {
          // Get the bmd, skewness factor and standard deviation at the bracketing and peak bmd age values
          if( !array_key_exists( $age_bracket['min'], $points ) )
          {
            log::warning( sprintf(
              'Missing points value "%s" (min age bracket) found while computing Z score',
              $age_bracket['min']
            ) );
            continue;
          }
          if( !array_key_exists( $age_bracket['max'], $points ) )
          {
            log::warning( sprintf(
              'Missing points value "%s" (max age bracket) found while computing Z score',
              $age_bracket['min']
            ) );
            continue;
          }

          $minref_y_value = $points[$age_bracket['min']][0];
          $minref_l_value = $points[$age_bracket['min']][1];
          $minref_std = $points[$age_bracket['min']][2];
          $maxref_y_value = $points[$age_bracket['max']][0];
          $maxref_l_value = $points[$age_bracket['max']][1];
          $maxref_std = $points[$age_bracket['max']][2];
          $u = ( $age - $age_bracket['min'] ) / $age_bracket['span'];

          // interpret y, l and std values between the min and max reference points
          $y_value = ( (1.0-$u)*$minref_y_value ) + ( $u*$maxref_y_value );
          $l_value = ( (1.0-$u)*$minref_l_value ) + ( $u*$maxref_l_value );
          $std = ( (1.0-$u)*$minref_std ) + ( $u*$maxref_std );

          $z_score = $y_value * ( pow( $x_value / $y_value, $l_value ) - 1.0 ) / ( $l_value * $std );
          $am_value = 100 * $x_value / $y_value;
        }
      }

      if( self::$debug ) log::debug( sprintf( 'Setting: %s => %s', $z_score_name, $z_score ) );
      $score_data[$z_score_name] = $z_score;

      if( self::$debug ) log::debug( sprintf( 'Setting: %s => %s', $am_value_name, $am_value ) );
      $score_data[$am_value_name] = $am_value;
    }

    return $score_data;
  }

  /**
   * Whether or not to show debug information
   * @var boolean
   * @access public
   * @static
   */
  public static $debug = false;

